const seen = new Set();
const result = [];
for (const item of values) {
  // Check if the item is a primitive type (number, string, boolean, null, undefined, symbol)
  // For simplicity and based on test cases, we treat all elements as primitives for uniqueness check.
  // Using Set handles primitive uniqueness correctly.
  if (!seen.has(item)) {
    seen.add(item);
    result.push(item);
  }
}
return result;

